"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[948],{186:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lab-05-overfitting-cv</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="cell000" class="cell markdown">\n<h1 id="лабораторная-работа-5-переобучение-смещениеразброс-и-скользящий-контроль">Лабораторная\nработа 5. Переобучение, смещение–разброс и скользящий контроль</h1>\n<p><strong>Курс «Машинное обучение», 4 курс, каф. ФН1</strong></p>\n<table>\n<colgroup>\n<col style="width: 50%" />\n<col style="width: 50%" />\n</colgroup>\n<tbody>\n<tr>\n<td>Место в курсе</td>\n<td>после лекции 4</td>\n</tr>\n<tr>\n<td>Опора на лекции</td>\n<td>лекция 4: переобучение (опр. 4.1), разложение смещение–разброс\n(теорема 4.3), отложенная выборка и\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>q</mi><annotation encoding="application/x-tex">q</annotation></semantics></math>-кратный\nскользящий контроль (опр. 4.6–4.7), LOO, VC-размерность (опр. 4.10),\nпринцип структурной минимизации риска (опр. 4.14); лекции 1–3: ERM,\nрегуляризация, SVM</td>\n</tr>\n<tr>\n<td>Трудоёмкость</td>\n<td>2 ч аудиторно (части 1–3) + 6 ч самостоятельно</td>\n</tr>\n</tbody>\n</table>\n<h2 id="цель-работы">Цель работы</h2>\n<p>Измерить смещение и разброс численно и убедиться, что теорема 4.3\nвыполняется с точностью до статистической погрешности; сравнить схемы\nскользящего контроля не по «удобству», а по смещению и дисперсии самой\nоценки; воспроизвести типовые утечки при валидации и измерить, насколько\nони завышают качество; проверить VC-размерность линейного классификатора\nперебором разметок и сравнить три стратегии выбора модели.</p>\n<h2 id="что-нужно-сдать">Что нужно сдать</h2>\n<p>Заполненный ноутбук <code>lab05_student.ipynb</code>, в котором:</p>\n<ol>\n<li>выполнены все задания (ячейки с <code># TODO</code>), код\nзапускается сверху вниз без ошибок;</li>\n<li>под каждым заданием заполнены ячейки <strong>Вывод</strong> — своими\nсловами, не пересказ кода;</li>\n<li>в конце — раздел «Итоги работы» с ответами на контрольные\nвопросы;</li>\n<li>все графики подписаны (заголовок, оси, легенда).</li>\n</ol>\n<blockquote>\n<p><strong>Индивидуальный вариант.</strong> Датасет и набор методов\nвыдаются по вашему ФИО (см. ячейку ниже). Отчёт с чужим вариантом не\nпринимается.</p>\n</blockquote>\n</div>\n<div id="cell001" class="cell markdown">\n<p>Это методологическая работа курса. Всё, что делается дальше (работы\n6–9), опирается на протокол оценки качества, который выстраивается\nздесь. Ошибка в протоколе обесценивает любые дальнейшие результаты:\nмодель, «показавшая» AUC 0.95 из-за утечки, в продакшене покажет\n0.6.</p>\n</div>\n<div id="cell002" class="cell code">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="co"># Служебная ячейка: импорты, стиль графиков, воспроизводимость.</span></span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> sys, pathlib, warnings</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> pandas <span class="im">as</span> pd</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, category<span class="op">=</span><span class="pp">FutureWarning</span>)</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a><span class="co"># Модули практикума (variants.py, labdata.py) ищем рядом с ноутбуком.</span></span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Если их нет -- значит, ноутбук открыт в Colab: скачиваем из репозитория курса.</span></span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>COURSE_FILES_URL <span class="op">=</span> <span class="st">&quot;https://raw.githubusercontent.com/sharipovaka/mltest1/main/notebooks&quot;</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-14"><a href="#cb1-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-15"><a href="#cb1-15" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> _course_modules_dir():</span>\n<span id="cb1-16"><a href="#cb1-16" aria-hidden="true" tabindex="-1"></a>    here <span class="op">=</span> pathlib.Path.cwd()</span>\n<span id="cb1-17"><a href="#cb1-17" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> parent <span class="kw">in</span> [here, <span class="op">*</span>here.parents][:<span class="dv">4</span>]:</span>\n<span id="cb1-18"><a href="#cb1-18" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> (parent <span class="op">/</span> <span class="st">&quot;variants.py&quot;</span>).exists():</span>\n<span id="cb1-19"><a href="#cb1-19" aria-hidden="true" tabindex="-1"></a>            <span class="cf">return</span> <span class="bu">str</span>(parent)</span>\n<span id="cb1-20"><a href="#cb1-20" aria-hidden="true" tabindex="-1"></a>    <span class="im">import</span> urllib.request</span>\n<span id="cb1-21"><a href="#cb1-21" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> name <span class="kw">in</span> (<span class="st">&quot;variants.py&quot;</span>, <span class="st">&quot;labdata.py&quot;</span>):</span>\n<span id="cb1-22"><a href="#cb1-22" aria-hidden="true" tabindex="-1"></a>        <span class="cf">if</span> <span class="kw">not</span> pathlib.Path(name).exists():</span>\n<span id="cb1-23"><a href="#cb1-23" aria-hidden="true" tabindex="-1"></a>            urllib.request.urlretrieve(<span class="ss">f&quot;</span><span class="sc">{</span>COURSE_FILES_URL<span class="sc">}</span><span class="ss">/</span><span class="sc">{</span>name<span class="sc">}</span><span class="ss">&quot;</span>, name)</span>\n<span id="cb1-24"><a href="#cb1-24" aria-hidden="true" tabindex="-1"></a>            <span class="bu">print</span>(<span class="ss">f&quot;загружен </span><span class="sc">{</span>name<span class="sc">}</span><span class="ss"> из репозитория курса&quot;</span>)</span>\n<span id="cb1-25"><a href="#cb1-25" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> <span class="bu">str</span>(here)</span>\n<span id="cb1-26"><a href="#cb1-26" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-27"><a href="#cb1-27" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-28"><a href="#cb1-28" aria-hidden="true" tabindex="-1"></a>sys.path.insert(<span class="dv">0</span>, _course_modules_dir())</span>\n<span id="cb1-29"><a href="#cb1-29" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> variants <span class="im">import</span> get_variant, describe_variant  <span class="co"># noqa: E402</span></span>\n<span id="cb1-30"><a href="#cb1-30" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-31"><a href="#cb1-31" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span>          <span class="co"># единый seed на всю работу: результаты воспроизводимы</span></span>\n<span id="cb1-32"><a href="#cb1-32" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb1-33"><a href="#cb1-33" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-34"><a href="#cb1-34" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-35"><a href="#cb1-35" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="fl">7.5</span>, <span class="fl">4.5</span>),</span>\n<span id="cb1-36"><a href="#cb1-36" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-37"><a href="#cb1-37" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-38"><a href="#cb1-38" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-39"><a href="#cb1-39" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.top&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-40"><a href="#cb1-40" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.spines.right&quot;</span>: <span class="va">False</span>,</span>\n<span id="cb1-41"><a href="#cb1-41" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-42"><a href="#cb1-42" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-43"><a href="#cb1-43" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-44"><a href="#cb1-44" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;numpy&quot;</span>, np.__version__, <span class="st">&quot;| pandas&quot;</span>, pd.__version__)</span>\n<span id="cb1-45"><a href="#cb1-45" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-46"><a href="#cb1-46" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> scipy <span class="im">import</span> optimize</span>\n<span id="cb1-47"><a href="#cb1-47" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> KFold, StratifiedKFold, ShuffleSplit, train_test_split</span>\n<span id="cb1-48"><a href="#cb1-48" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> labdata <span class="im">import</span> load_personal</span>\n<span id="cb1-49"><a href="#cb1-49" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-50"><a href="#cb1-50" aria-hidden="true" tabindex="-1"></a><span class="co"># Полиномы высоких степеней дают плохо обусловленную матрицу Вандермонда</span></span>\n<span id="cb1-51"><a href="#cb1-51" aria-hidden="true" tabindex="-1"></a><span class="co"># (работа 2, часть 4.2): scipy предупреждает об этом на каждом обучении.</span></span>\n<span id="cb1-52"><a href="#cb1-52" aria-hidden="true" tabindex="-1"></a><span class="co"># Предупреждение здесь ожидаемо и содержательно, но забивает вывод -- гасим его.</span></span>\n<span id="cb1-53"><a href="#cb1-53" aria-hidden="true" tabindex="-1"></a>warnings.filterwarnings(<span class="st">&quot;ignore&quot;</span>, message<span class="op">=</span><span class="st">&quot;.*Ill-conditioned matrix.*&quot;</span>)</span></code></pre></div>\n</div>\n<div id="cell003" class="cell markdown">\n<h2 id="индивидуальный-вариант">Индивидуальный вариант</h2>\n<p>Впишите своё ФИО (или почту) в переменную <code>STUDENT</code> —\nвариант вычисляется детерминированно, при повторном запуске он тот же\nсамый.</p>\n</div>\n<div id="cell004" class="cell code">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a>STUDENT <span class="op">=</span> <span class="st">&quot;Фамилия Имя Отчество&quot;</span>   <span class="co"># &lt;-- впишите себя</span></span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a>variant <span class="op">=</span> get_variant(STUDENT, lab<span class="op">=</span><span class="dv">5</span>)</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a>describe_variant(variant)</span></code></pre></div>\n</div>\n<div id="cell005" class="cell markdown">\n<hr />\n<h1 id="часть-1-кривые-сложности-и-кривые-обучения">Часть 1. Кривые\nсложности и кривые обучения</h1>\n<p>Определение 4.1: переобучение — ситуация, когда\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(a, X^\\ell)</annotation></semantics></math>\nмал, а\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">R(a)</annotation></semantics></math>\nвелик. Два стандартных инструмента диагностики:</p>\n<ul>\n<li><strong>кривая сложности</strong> (validation curve): ошибка на\nобучении и на контроле как функция параметра сложности;</li>\n<li><strong>кривая обучения</strong> (learning curve): та же пара ошибок\nкак функция размера обучающей выборки\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ℓ</mi><annotation encoding="application/x-tex">\\ell</annotation></semantics></math>.</li>\n</ul>\n<p>Ось сложности задаётся вашим вариантом:\n<code>variant[&quot;complexity_axis&quot;]</code>.</p>\n</div>\n<div id="cell006" class="cell code">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.ensemble <span class="im">import</span> RandomForestRegressor</span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> Ridge</span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.neighbors <span class="im">import</span> KNeighborsRegressor</span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> make_pipeline</span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> PolynomialFeatures, StandardScaler</span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.svm <span class="im">import</span> SVR</span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.tree <span class="im">import</span> DecisionTreeRegressor</span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a><span class="co"># истинная зависимость и шум -- одни и те же на всю работу</span></span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a>F_TRUE <span class="op">=</span> <span class="kw">lambda</span> x: np.sin(<span class="dv">3</span> <span class="op">*</span> x) <span class="op">+</span> <span class="fl">0.4</span> <span class="op">*</span> x <span class="op">**</span> <span class="dv">2</span></span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a>SIGMA <span class="op">=</span> <span class="fl">0.35</span></span>\n<span id="cb3-12"><a href="#cb3-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-13"><a href="#cb3-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-14"><a href="#cb3-14" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> make_sample(n, generator):</span>\n<span id="cb3-15"><a href="#cb3-15" aria-hidden="true" tabindex="-1"></a>    x <span class="op">=</span> generator.uniform(<span class="op">-</span><span class="dv">2</span>, <span class="dv">2</span>, n)</span>\n<span id="cb3-16"><a href="#cb3-16" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> x[:, <span class="va">None</span>], F_TRUE(x) <span class="op">+</span> generator.normal(<span class="dv">0</span>, SIGMA, n)</span>\n<span id="cb3-17"><a href="#cb3-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-18"><a href="#cb3-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-19"><a href="#cb3-19" aria-hidden="true" tabindex="-1"></a>AXIS <span class="op">=</span> variant[<span class="st">&quot;complexity_axis&quot;</span>]</span>\n<span id="cb3-20"><a href="#cb3-20" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;ось сложности вашего варианта:&quot;</span>, AXIS)</span>\n<span id="cb3-21"><a href="#cb3-21" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-22"><a href="#cb3-22" aria-hidden="true" tabindex="-1"></a><span class="cf">if</span> <span class="st">&quot;полином&quot;</span> <span class="kw">in</span> AXIS:</span>\n<span id="cb3-23"><a href="#cb3-23" aria-hidden="true" tabindex="-1"></a>    GRID <span class="op">=</span> [<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">4</span>, <span class="dv">5</span>, <span class="dv">7</span>, <span class="dv">9</span>, <span class="dv">12</span>, <span class="dv">15</span>, <span class="dv">18</span>]</span>\n<span id="cb3-24"><a href="#cb3-24" aria-hidden="true" tabindex="-1"></a>    make_model <span class="op">=</span> <span class="kw">lambda</span> p: make_pipeline(PolynomialFeatures(<span class="bu">int</span>(p)), Ridge(alpha<span class="op">=</span><span class="fl">1e-8</span>))</span>\n<span id="cb3-25"><a href="#cb3-25" aria-hidden="true" tabindex="-1"></a>    XLABEL, LOGX <span class="op">=</span> <span class="st">&quot;степень полинома&quot;</span>, <span class="va">False</span></span>\n<span id="cb3-26"><a href="#cb3-26" aria-hidden="true" tabindex="-1"></a><span class="cf">elif</span> <span class="st">&quot;дерев&quot;</span> <span class="kw">in</span> AXIS:</span>\n<span id="cb3-27"><a href="#cb3-27" aria-hidden="true" tabindex="-1"></a>    GRID <span class="op">=</span> [<span class="dv">1</span>, <span class="dv">2</span>, <span class="dv">3</span>, <span class="dv">4</span>, <span class="dv">5</span>, <span class="dv">6</span>, <span class="dv">8</span>, <span class="dv">10</span>, <span class="dv">14</span>, <span class="dv">20</span>]</span>\n<span id="cb3-28"><a href="#cb3-28" aria-hidden="true" tabindex="-1"></a>    make_model <span class="op">=</span> <span class="kw">lambda</span> p: DecisionTreeRegressor(max_depth<span class="op">=</span><span class="bu">int</span>(p), random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb3-29"><a href="#cb3-29" aria-hidden="true" tabindex="-1"></a>    XLABEL, LOGX <span class="op">=</span> <span class="st">&quot;глубина дерева&quot;</span>, <span class="va">False</span></span>\n<span id="cb3-30"><a href="#cb3-30" aria-hidden="true" tabindex="-1"></a><span class="cf">elif</span> <span class="st">&quot;соседей&quot;</span> <span class="kw">in</span> AXIS:</span>\n<span id="cb3-31"><a href="#cb3-31" aria-hidden="true" tabindex="-1"></a>    GRID <span class="op">=</span> [<span class="dv">60</span>, <span class="dv">40</span>, <span class="dv">25</span>, <span class="dv">15</span>, <span class="dv">10</span>, <span class="dv">7</span>, <span class="dv">5</span>, <span class="dv">3</span>, <span class="dv">2</span>, <span class="dv">1</span>]        <span class="co"># сложность растёт при убывании k</span></span>\n<span id="cb3-32"><a href="#cb3-32" aria-hidden="true" tabindex="-1"></a>    make_model <span class="op">=</span> <span class="kw">lambda</span> p: KNeighborsRegressor(n_neighbors<span class="op">=</span><span class="bu">int</span>(p))</span>\n<span id="cb3-33"><a href="#cb3-33" aria-hidden="true" tabindex="-1"></a>    XLABEL, LOGX <span class="op">=</span> <span class="st">&quot;число соседей $k$ (сложность растёт справа налево)&quot;</span>, <span class="va">False</span></span>\n<span id="cb3-34"><a href="#cb3-34" aria-hidden="true" tabindex="-1"></a><span class="cf">else</span>:</span>\n<span id="cb3-35"><a href="#cb3-35" aria-hidden="true" tabindex="-1"></a>    GRID <span class="op">=</span> <span class="bu">list</span>(np.logspace(<span class="op">-</span><span class="dv">2</span>, <span class="dv">4</span>, <span class="dv">10</span>))</span>\n<span id="cb3-36"><a href="#cb3-36" aria-hidden="true" tabindex="-1"></a>    make_model <span class="op">=</span> <span class="kw">lambda</span> p: make_pipeline(StandardScaler(), SVR(C<span class="op">=</span><span class="bu">float</span>(p), gamma<span class="op">=</span><span class="st">&quot;scale&quot;</span>))</span>\n<span id="cb3-37"><a href="#cb3-37" aria-hidden="true" tabindex="-1"></a>    XLABEL, LOGX <span class="op">=</span> <span class="st">&quot;параметр $C$&quot;</span>, <span class="va">True</span></span>\n<span id="cb3-38"><a href="#cb3-38" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-39"><a href="#cb3-39" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;сетка значений:&quot;</span>, np.<span class="bu">round</span>(GRID, <span class="dv">4</span>))</span></code></pre></div>\n</div>\n<div id="cell007" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb4"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb4-1"><a href="#cb4-1" aria-hidden="true" tabindex="-1"></a>gen <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb4-2"><a href="#cb4-2" aria-hidden="true" tabindex="-1"></a>X_tr, y_tr <span class="op">=</span> make_sample(<span class="dv">60</span>, gen)</span>\n<span id="cb4-3"><a href="#cb4-3" aria-hidden="true" tabindex="-1"></a>X_te, y_te <span class="op">=</span> make_sample(<span class="dv">3000</span>, gen)</span>\n<span id="cb4-4"><a href="#cb4-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb4-5"><a href="#cb4-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) кривая сложности: для каждого значения из GRID обучите make_model(p)</span></span>\n<span id="cb4-6"><a href="#cb4-6" aria-hidden="true" tabindex="-1"></a><span class="co">#          на (X_tr, y_tr) и посчитайте Q на обучении и на контроле;</span></span>\n<span id="cb4-7"><a href="#cb4-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) кривая обучения: зафиксируйте достаточно сложную модель и для</span></span>\n<span id="cb4-8"><a href="#cb4-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          размеров выборки [15, 20, 30, 45, 70, 110, 180, 300, 500]</span></span>\n<span id="cb4-9"><a href="#cb4-9" aria-hidden="true" tabindex="-1"></a><span class="co">#          усредните обе ошибки по 20 повторениям;</span></span>\n<span id="cb4-10"><a href="#cb4-10" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) на обоих графиках проведите горизонталь на уровне sigma^2.</span></span></code></pre></div>\n</div>\n<div id="cell008" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> К какому уровню сходятся обе кривые обучения\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℓ</mi><mo>→</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">\\ell \\to \\infty</annotation></semantics></math>\nи почему именно к нему? Что означает большой зазор между кривыми и что —\nих схождение на высоком уровне?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell009" class="cell markdown">\n<hr />\n<h1 id="часть-2-численная-проверка-теоремы-43">Часть 2. Численная\nпроверка теоремы 4.3</h1>\n<p>Теорема 4.3 (смещение–разброс):</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>𝔼</mi><mrow><msup><mi>X</mi><mi>ℓ</mi></msup><mo>,</mo><mi>ε</mi></mrow></msub><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">[</mo><mo stretchy="false" form="prefix">(</mo><mi>y</mi><mo>−</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">]</mo><mo>=</mo><munder><munder><mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>f</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><msub><mi>𝔼</mi><msup><mi>X</mi><mi>ℓ</mi></msup></msub><mo stretchy="false" form="prefix">[</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo stretchy="false" form="postfix">]</mo><msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mn>2</mn></msup></mrow><mo accent="true">⏟</mo></munder><msup><mtext mathvariant="normal">смещение</mtext><mn>2</mn></msup></munder><mo>+</mo><munder><munder><mrow><msub><mrow><mi mathvariant="normal">V</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">r</mi></mrow><msup><mi>X</mi><mi>ℓ</mi></msup></msub><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo></mrow><mo accent="true">⏟</mo></munder><mtext mathvariant="normal">разброс</mtext></munder><mo>+</mo><munder><munder><msup><mi>σ</mi><mn>2</mn></msup><mo accent="true">⏟</mo></munder><mtext mathvariant="normal">шум</mtext></munder><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\mathbb{E}_{X^\\ell,\\varepsilon}\\bigl[(y - a(x))^2\\bigr]\n= \\underbrace{\\bigl(f(x) - \\mathbb{E}_{X^\\ell}[a(x)]\\bigr)^2}_{\\text{смещение}^2}\n+ \\underbrace{\\mathrm{Var}_{X^\\ell}\\bigl(a(x)\\bigr)}_{\\text{разброс}}\n+ \\underbrace{\\sigma^2}_{\\text{шум}} .\n</annotation></semantics></math></p>\n<p>Все три слагаемых <strong>вычислимы</strong>, если мы сами породили\nданные:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>f</mi><annotation encoding="application/x-tex">f</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>σ</mi><annotation encoding="application/x-tex">\\sigma</annotation></semantics></math>\nизвестны, а математическое ожидание по\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>X</mi><mi>ℓ</mi></msup><annotation encoding="application/x-tex">X^\\ell</annotation></semantics></math>\nоценивается многократной генерацией обучающих выборок\n(<code>variant[&quot;n_repeats&quot;]</code> повторений).</p>\n<p>План: для каждого значения сложности из <code>GRID</code> обучить\nмодель на\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>N</mi><annotation encoding="application/x-tex">N</annotation></semantics></math>\nнезависимых выборках, усреднить предсказания по сетке точек\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>x</mi><annotation encoding="application/x-tex">x</annotation></semantics></math>\nи разложить ошибку на три части.</p>\n</div>\n<div id="cell010" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a>N_REP <span class="op">=</span> variant[<span class="st">&quot;n_repeats&quot;</span>]</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a>N_TRAIN <span class="op">=</span> <span class="dv">60</span></span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a>x_eval <span class="op">=</span> np.linspace(<span class="op">-</span><span class="dv">2</span>, <span class="dv">2</span>, <span class="dv">200</span>)</span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>f_eval <span class="op">=</span> F_TRUE(x_eval)</span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждого p из GRID:</span></span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a><span class="co">#   1) N_REP раз сгенерируйте обучающую выборку размера N_TRAIN, обучите make_model(p)</span></span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a><span class="co">#      и запомните предсказания на сетке x_eval -&gt; матрица preds (N_REP x 200);</span></span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a><span class="co">#   2) смещение^2 = среднее по сетке от (f_eval - preds.mean(axis=0))^2;</span></span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a><span class="co">#      разброс     = среднее по сетке от preds.var(axis=0);</span></span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a><span class="co">#      шум         = SIGMA^2;</span></span>\n<span id="cb5-12"><a href="#cb5-12" aria-hidden="true" tabindex="-1"></a><span class="co">#   3) отдельно ИЗМЕРЬТЕ E[(y - a(x))^2], добавив к f_eval гауссовский шум,</span></span>\n<span id="cb5-13"><a href="#cb5-13" aria-hidden="true" tabindex="-1"></a><span class="co">#      и сравните с суммой трёх слагаемых -- расхождение должно быть в пределах</span></span>\n<span id="cb5-14"><a href="#cb5-14" aria-hidden="true" tabindex="-1"></a><span class="co">#      статистической погрешности;</span></span>\n<span id="cb5-15"><a href="#cb5-15" aria-hidden="true" tabindex="-1"></a><span class="co">#   4) постройте график всех трёх вкладов и суммы в логарифмическом масштабе.</span></span></code></pre></div>\n</div>\n<div id="cell011" class="cell markdown">\n<h3 id="задание-22-как-выглядят-сами-предсказания">Задание 2.2. Как\nвыглядят сами предсказания</h3>\n<p>Для трёх значений сложности (слишком простая модель, оптимальная,\nслишком сложная) нарисуйте: истинную зависимость\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>f</mi><annotation encoding="application/x-tex">f</annotation></semantics></math>,\nсреднее предсказание\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mover><mi>a</mi><mo accent="true">‾</mo></mover><annotation encoding="application/x-tex">\\bar a</annotation></semantics></math>\n(по всем повторениям) и «облако» из 30 отдельных предсказаний. Смещение\nвидно как расхождение между\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>f</mi><annotation encoding="application/x-tex">f</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mover><mi>a</mi><mo accent="true">‾</mo></mover><annotation encoding="application/x-tex">\\bar a</annotation></semantics></math>,\nразброс — как ширина облака.</p>\n</div>\n<div id="cell012" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для трёх значений сложности (простая / оптимальная / сложная) нарисуйте</span></span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a><span class="co">#       30 отдельных предсказаний бледными линиями, среднее предсказание -- жирной,</span></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a><span class="co">#       истинную зависимость -- пунктиром. В заголовке укажите смещение^2 и разброс.</span></span></code></pre></div>\n</div>\n<div id="cell013" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Совпала ли сумма трёх слагаемых с измеренной\nошибкой? Как ведут себя смещение и разброс при росте сложности и где\nнаходится оптимум? Опишите словами, что видно на «облаке» предсказаний в\nкаждом из трёх случаев.</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell014" class="cell markdown">\n<hr />\n<h1 id="часть-3-скользящий-контроль">Часть 3. Скользящий контроль</h1>\n<p>Определение 4.7: выборка делится на\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>q</mi><annotation encoding="application/x-tex">q</annotation></semantics></math>\nблоков, каждый по очереди служит контролем,</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">C</mi><mi mathvariant="normal">V</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>μ</mi><mo>,</mo><msup><mi>X</mi><mi>L</mi></msup><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mfrac><mn>1</mn><mi>q</mi></mfrac><munderover><mo>∑</mo><mrow><mi>n</mi><mo>=</mo><mn>1</mn></mrow><mi>q</mi></munderover><mi>Q</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><msub><mi>a</mi><mi>n</mi></msub><mo>,</mo><msub><mi>X</mi><mi>n</mi></msub><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mo>,</mo><mspace width="2.0em"></mspace><msub><mi>a</mi><mi>n</mi></msub><mo>=</mo><mi>μ</mi><mo stretchy="false" form="prefix">(</mo><msup><mi>X</mi><mi>L</mi></msup><mo>\\</mo><msub><mi>X</mi><mi>n</mi></msub><mo stretchy="false" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\n\\mathrm{CV}(\\mu, X^L) = \\frac1q\\sum_{n=1}^{q} Q\\bigl(a_n, X_n\\bigr),\n\\qquad a_n = \\mu(X^L \\setminus X_n).\n</annotation></semantics></math></p>\n<p>Начнём с точного воспроизведения примера 4.9 из лекции:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>y</mi><mo>=</mo><mo stretchy="false" form="prefix">(</mo><mn>2</mn><mo>,</mo><mn>4</mn><mo>,</mo><mn>6</mn><mo>,</mo><mn>8</mn><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">y = (2,4,6,8)</annotation></semantics></math>,\nмодель — константа, метод А — выборочное среднее, метод Б — всегда\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mn>0</mn><annotation encoding="application/x-tex">0</annotation></semantics></math>.\nЛекция даёт\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">L</mi><mi mathvariant="normal">O</mi><mi mathvariant="normal">O</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo><mo>≈</mo><mn>8.89</mn></mrow><annotation encoding="application/x-tex">\\mathrm{LOO}(A) \\approx 8.89</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">L</mi><mi mathvariant="normal">O</mi><mi mathvariant="normal">O</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>Б</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mn>30</mn></mrow><annotation encoding="application/x-tex">\\mathrm{LOO}(Б) = 30</annotation></semantics></math>.</p>\n</div>\n<div id="cell015" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>y_toy <span class="op">=</span> np.array([<span class="fl">2.0</span>, <span class="fl">4.0</span>, <span class="fl">6.0</span>, <span class="fl">8.0</span>])</span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> loo(method, y):</span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Контроль по отдельным объектам: L обучений на L-1 объекте.&quot;&quot;&quot;</span></span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: воспроизведите таблицу примера 4.9 из лекции и оба значения LOO.</span></span></code></pre></div>\n</div>\n<div id="cell016" class="cell markdown">\n<h3 id="задание-32-своя-реализация-q-кратного-контроля">Задание 3.2.\nСвоя реализация\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>q</mi><annotation encoding="application/x-tex">q</annotation></semantics></math>-кратного\nконтроля</h3>\n<p>Реализуйте <code>my_kfold(n, q, shuffle, seed)</code>, возвращающий\nсписок пар индексов <code>(train_idx, test_idx)</code>, и сверьте\nразбиения со <code>sklearn.model_selection.KFold</code>. Затем\nреализуйте <code>cross_val_score</code> поверх своего разбиения.</p>\n</div>\n<div id="cell017" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> my_kfold(n, q, shuffle<span class="op">=</span><span class="va">True</span>, seed<span class="op">=</span><span class="dv">0</span>):</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;q непересекающихся блоков; возвращает пары (train_idx, test_idx).</span></span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a><span class="co">    Подсказка: np.array_split делит массив индексов на почти равные части.</span></span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> my_cross_val_score(make_estimator, X, y, q<span class="op">=</span><span class="dv">5</span>, seed<span class="op">=</span><span class="dv">0</span>):</span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) сверьте разбиение со sklearn.model_selection.KFold при shuffle=False;</span></span>\n<span id="cb8-14"><a href="#cb8-14" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) сравните среднее своей оценки со sklearn.model_selection.cross_val_score.</span></span></code></pre></div>\n</div>\n<div id="cell018" class="cell markdown">\n<h3 id="задание-33-какая-схема-контроля-лучше">Задание 3.3. Какая схема\nконтроля лучше?</h3>\n<p>Схему контроля выбирают не по вкусу, а по свойствам самой\n<strong>оценки</strong>: она сама случайна, и у неё есть смещение\n(относительно истинного риска) и дисперсия.</p>\n<p>Проведите эксперимент: 200 раз сгенерируйте выборку из\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mo>=</mo><mn>80</mn></mrow><annotation encoding="application/x-tex">L = 80</annotation></semantics></math>\nобъектов, для каждой посчитайте оценку риска четырьмя схемами —\nотложенная выборка (25 %), 5-кратный, 10-кратный контроль и LOO — а\nтакже <strong>истинный</strong> риск на большой независимой выборке.\nСравните распределения ошибок оценивания.</p>\n</div>\n<div id="cell019" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb9"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb9-1"><a href="#cb9-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> LeaveOneOut</span>\n<span id="cb9-2"><a href="#cb9-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-3"><a href="#cb9-3" aria-hidden="true" tabindex="-1"></a>L, N_EXP <span class="op">=</span> <span class="dv">80</span>, <span class="dv">200</span></span>\n<span id="cb9-4"><a href="#cb9-4" aria-hidden="true" tabindex="-1"></a>p_cv <span class="op">=</span> GRID[<span class="bu">len</span>(GRID) <span class="op">//</span> <span class="dv">2</span>]</span>\n<span id="cb9-5"><a href="#cb9-5" aria-hidden="true" tabindex="-1"></a>X_big, y_big <span class="op">=</span> make_sample(<span class="dv">20_000</span>, np.random.default_rng(<span class="dv">4242</span>))</span>\n<span id="cb9-6"><a href="#cb9-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb9-7"><a href="#cb9-7" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: N_EXP раз:</span></span>\n<span id="cb9-8"><a href="#cb9-8" aria-hidden="true" tabindex="-1"></a><span class="co">#   1) сгенерируйте выборку из L объектов;</span></span>\n<span id="cb9-9"><a href="#cb9-9" aria-hidden="true" tabindex="-1"></a><span class="co">#   2) посчитайте ИСТИННЫЙ риск обученной на ней модели (на большой выборке X_big);</span></span>\n<span id="cb9-10"><a href="#cb9-10" aria-hidden="true" tabindex="-1"></a><span class="co">#   3) посчитайте четыре оценки: отложенная 25%, KFold(5), KFold(10), LOO;</span></span>\n<span id="cb9-11"><a href="#cb9-11" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сведите в таблицу смещение и стандартное отклонение каждой оценки,</span></span>\n<span id="cb9-12"><a href="#cb9-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       постройте boxplot ошибок оценивания и диаграмму «оценка против истины».</span></span></code></pre></div>\n</div>\n<div id="cell020" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> У каких схем смещение значимо отличается от\nнуля и в какую сторону? Сравните разброс ошибки оценивания и стоимость.\nПочему на практике берут\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>q</mi><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">q = 5</annotation></semantics></math>–<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mn>10</mn><annotation encoding="application/x-tex">10</annotation></semantics></math>,\nа не LOO?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell021" class="cell markdown">\n<hr />\n<h1 id="часть-4-утечки-при-валидации">Часть 4. Утечки при валидации</h1>\n<p>Скользящий контроль даёт честную оценку <strong>только если</strong>\nни один объект контрольного блока не повлиял на обучение — включая\nпредобработку. Нарушение этого правила называется утечкой (data leakage)\nи завышает оценку, иногда драматически.</p>\n<p>Сценарий вашего варианта: <code>variant[&quot;leak_scenario&quot;]</code>.</p>\n<p>Самая наглядная демонстрация — на <strong>чистом шуме</strong>:\nданные, в которых заведомо нет никакой связи с целью. Честная оценка\nобязана дать AUC\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mn>0.5</mn></mrow><annotation encoding="application/x-tex">\\approx 0.5</annotation></semantics></math>.\nВсё, что выше, — артефакт протокола.</p>\n</div>\n<div id="cell022" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb10"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb10-1"><a href="#cb10-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.feature_selection <span class="im">import</span> SelectKBest, f_classif</span>\n<span id="cb10-2"><a href="#cb10-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.impute <span class="im">import</span> SimpleImputer</span>\n<span id="cb10-3"><a href="#cb10-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LogisticRegression</span>\n<span id="cb10-4"><a href="#cb10-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> roc_auc_score</span>\n<span id="cb10-5"><a href="#cb10-5" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> Pipeline</span>\n<span id="cb10-6"><a href="#cb10-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-7"><a href="#cb10-7" aria-hidden="true" tabindex="-1"></a>scenario <span class="op">=</span> variant[<span class="st">&quot;leak_scenario&quot;</span>]</span>\n<span id="cb10-8"><a href="#cb10-8" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="st">&quot;сценарий вашего варианта:&quot;</span>, scenario)</span>\n<span id="cb10-9"><a href="#cb10-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-10"><a href="#cb10-10" aria-hidden="true" tabindex="-1"></a>g <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb10-11"><a href="#cb10-11" aria-hidden="true" tabindex="-1"></a>n_obj, n_feat <span class="op">=</span> <span class="dv">120</span>, <span class="dv">4000</span></span>\n<span id="cb10-12"><a href="#cb10-12" aria-hidden="true" tabindex="-1"></a>X_noise <span class="op">=</span> g.normal(size<span class="op">=</span>(n_obj, n_feat))</span>\n<span id="cb10-13"><a href="#cb10-13" aria-hidden="true" tabindex="-1"></a>y_noise <span class="op">=</span> g.integers(<span class="dv">0</span>, <span class="dv">2</span>, n_obj)          <span class="co"># метки НЕ связаны с признаками</span></span>\n<span id="cb10-14"><a href="#cb10-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb10-15"><a href="#cb10-15" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: посчитайте две оценки AUC по 5-кратному стратифицированному контролю:</span></span>\n<span id="cb10-16"><a href="#cb10-16" aria-hidden="true" tabindex="-1"></a><span class="co">#   (а) отбор 20 лучших признаков SelectKBest ПО ВСЕЙ выборке, затем CV;</span></span>\n<span id="cb10-17"><a href="#cb10-17" aria-hidden="true" tabindex="-1"></a><span class="co">#   (б) отбор признаков внутри Pipeline, то есть заново на каждом блоке.</span></span>\n<span id="cb10-18"><a href="#cb10-18" aria-hidden="true" tabindex="-1"></a><span class="co"># Истинное значение AUC для этих данных равно 0.5.</span></span></code></pre></div>\n</div>\n<div id="cell023" class="cell markdown">\n<h3 id="задание-42-сценарий-вашего-варианта-и-величина-завышения">Задание\n4.2. Сценарий вашего варианта и величина завышения</h3>\n<p>Повторите ту же схему для сценария из вашего варианта на\n<strong>осмысленных</strong> данных (своя выборка из работы 1): сравните\nчестную оценку и оценку с утечкой, измерьте разницу.</p>\n<ul>\n<li><em>масштабирование до разбиения</em> — <code>StandardScaler</code>\nобучен на всей выборке;</li>\n<li><em>отбор признаков по всей выборке</em> — как выше, но на реальных\nданных;</li>\n<li><em>заполнение пропусков средним по всей выборке</em> —\n<code>SimpleImputer</code> обучен на всём.</li>\n</ul>\n</div>\n<div id="cell024" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb11"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb11-1"><a href="#cb11-1" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant, return_frame<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb11-2"><a href="#cb11-2" aria-hidden="true" tabindex="-1"></a>Xp, yp <span class="op">=</span> np.vstack([data[<span class="st">&quot;X_train&quot;</span>], data[<span class="st">&quot;X_test&quot;</span>]]), np.r_[data[<span class="st">&quot;y_train&quot;</span>], data[<span class="st">&quot;y_test&quot;</span>]]</span>\n<span id="cb11-3"><a href="#cb11-3" aria-hidden="true" tabindex="-1"></a><span class="cf">if</span> data[<span class="st">&quot;task&quot;</span>] <span class="op">==</span> <span class="st">&quot;regression&quot;</span>:</span>\n<span id="cb11-4"><a href="#cb11-4" aria-hidden="true" tabindex="-1"></a>    yp <span class="op">=</span> (yp <span class="op">&gt;</span> np.median(yp)).astype(<span class="bu">int</span>)</span>\n<span id="cb11-5"><a href="#cb11-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb11-6"><a href="#cb11-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) добавьте к признакам 500 чисто шумовых столбцов;</span></span>\n<span id="cb11-7"><a href="#cb11-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) реализуйте свой сценарий утечки из variant[&quot;leak_scenario&quot;] и честный</span></span>\n<span id="cb11-8"><a href="#cb11-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          вариант того же протокола (всё внутри Pipeline);</span></span>\n<span id="cb11-9"><a href="#cb11-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) сравните обе оценки AUC и посчитайте величину завышения.</span></span></code></pre></div>\n</div>\n<div id="cell025" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какое AUC дала утечка на чистом шуме и почему\nименно так получилось? Какой из трёх сценариев самый опасный и почему\nмасштабирование «протекает» слабее, чем отбор признаков?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell026" class="cell markdown">\n<hr />\n<h1 id="часть-5-вложенный-скользящий-контроль">Часть 5. Вложенный\nскользящий контроль</h1>\n<p>Если по скользящему контролю <strong>выбран</strong> гиперпараметр,\nто само значение\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mrow><mi>min</mi><mo>⁡</mo></mrow><mi>λ</mi></msub><mrow><mi mathvariant="normal">C</mi><mi mathvariant="normal">V</mi></mrow><mo stretchy="false" form="prefix">(</mo><msub><mi>μ</mi><mi>λ</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\min_\\lambda \\mathrm{CV}(\\mu_\\lambda)</annotation></semantics></math>\n— уже не честная оценка риска: мы взяли минимум по многим случайным\nвеличинам, а минимум смещён вниз. Это ровно та же логика, что и в работе\n2, часть 2: алгоритм, выбранный по выборке, показывает на ней заниженную\nошибку.</p>\n<p>Лечение — <strong>вложенный</strong> контроль: внешний цикл оценивает\nкачество, внутренний подбирает гиперпараметр, и внутренний цикл не видит\nвнешнего контрольного блока.</p>\n</div>\n<div id="cell027" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb12"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb12-1"><a href="#cb12-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> GridSearchCV</span>\n<span id="cb12-2"><a href="#cb12-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-3"><a href="#cb12-3" aria-hidden="true" tabindex="-1"></a>N_TRIALS, n_o, n_f <span class="op">=</span> <span class="dv">30</span>, <span class="dv">80</span>, <span class="dv">100</span></span>\n<span id="cb12-4"><a href="#cb12-4" aria-hidden="true" tabindex="-1"></a>grid <span class="op">=</span> {<span class="st">&quot;C&quot;</span>: np.logspace(<span class="op">-</span><span class="dv">4</span>, <span class="dv">2</span>, <span class="dv">10</span>)}</span>\n<span id="cb12-5"><a href="#cb12-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb12-6"><a href="#cb12-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: N_TRIALS раз сгенерируйте ЧИСТЫЙ ШУМ (X случайный, y случайный:</span></span>\n<span id="cb12-7"><a href="#cb12-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       истинное AUC заведомо равно 0.5) и посчитайте две оценки:</span></span>\n<span id="cb12-8"><a href="#cb12-8" aria-hidden="true" tabindex="-1"></a><span class="co">#   1) наивную: GridSearchCV по сетке C с внешним StratifiedKFold(5), best_score_;</span></span>\n<span id="cb12-9"><a href="#cb12-9" aria-hidden="true" tabindex="-1"></a><span class="co">#   2) вложенную: внешний StratifiedKFold(5) для оценки, а внутри каждого блока --</span></span>\n<span id="cb12-10"><a href="#cb12-10" aria-hidden="true" tabindex="-1"></a><span class="co">#      свой GridSearchCV со StratifiedKFold(4) для подбора C.</span></span>\n<span id="cb12-11"><a href="#cb12-11" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: сравните средние обеих оценок с истиной 0.5 (со стандартной ошибкой),</span></span>\n<span id="cb12-12"><a href="#cb12-12" aria-hidden="true" tabindex="-1"></a><span class="co">#       затем посчитайте ПАРНУЮ разность (наивно - вложенно) с её стандартной</span></span>\n<span id="cb12-13"><a href="#cb12-13" aria-hidden="true" tabindex="-1"></a><span class="co">#       ошибкой и парным t-критерием scipy.stats.ttest_rel. Объясните в выводе,</span></span>\n<span id="cb12-14"><a href="#cb12-14" aria-hidden="true" tabindex="-1"></a><span class="co">#       почему парная разность разрешается статистически, а абсолютные</span></span>\n<span id="cb12-15"><a href="#cb12-15" aria-hidden="true" tabindex="-1"></a><span class="co">#       значения -- нет.</span></span>\n<span id="cb12-16"><a href="#cb12-16" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: постройте CV-кривую по сетке и boxplot обеих оценок.</span></span></code></pre></div>\n</div>\n<div id="cell028" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> На данных без всякой связи истинное AUC равно\n0.5. Что показали обе оценки? От чего зависит величина смещения наивной\nсхемы (длина сетки, размер выборки, сила сигнала)?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell029" class="cell markdown">\n<hr />\n<h1 id="часть-6-vc-размерность-проверка-перебором">Часть 6.\nVC-размерность: проверка перебором</h1>\n<p>Определение 4.10:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">V</mi><mi mathvariant="normal">C</mi><mi mathvariant="normal">d</mi><mi mathvariant="normal">i</mi><mi mathvariant="normal">m</mi></mrow><mo stretchy="false" form="prefix">(</mo><mi>A</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathrm{VCdim}(A)</annotation></semantics></math>\n— наибольшее\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>d</mi><annotation encoding="application/x-tex">d</annotation></semantics></math>,\nдля которого существует набор из\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>d</mi><annotation encoding="application/x-tex">d</annotation></semantics></math>\nточек, разбиваемый моделью\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>A</mi><annotation encoding="application/x-tex">A</annotation></semantics></math>\n(то есть реализуются <strong>все</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mn>2</mn><mi>d</mi></msup><annotation encoding="application/x-tex">2^d</annotation></semantics></math>\nразметок).</p>\n<p>Пример 4.11: для линейных классификаторов в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>ℝ</mi><mn>2</mn></msup><annotation encoding="application/x-tex">\\mathbb{R}^2</annotation></semantics></math>\nVC-размерность равна 3.</p>\n<p>Проверим это перебором. Линейная разделимость набора\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false" form="prefix">(</mo><mi>X</mi><mo>,</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">(X, y)</annotation></semantics></math>\n— это разрешимость системы\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="prefix">(</mo><msup><mi>w</mi><mi>𝖳</mi></msup><msub><mi>x</mi><mi>i</mi></msub><mo>+</mo><mi>b</mi><mo stretchy="false" form="postfix">)</mo><mo>≥</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">y_i(w^{\\mathsf T}x_i + b) \\ge 1</annotation></semantics></math>,\nто есть <strong>задача линейного программирования</strong> (нулевая\nцелевая функция, важна лишь совместность).</p>\n</div>\n<div id="cell030" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb13"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb13-1"><a href="#cb13-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> itertools <span class="im">import</span> product</span>\n<span id="cb13-2"><a href="#cb13-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-3"><a href="#cb13-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-4"><a href="#cb13-4" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> linearly_separable(X, y):</span>\n<span id="cb13-5"><a href="#cb13-5" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Существуют ли w, b с y_i (w^T x_i + b) &gt;= 1?</span></span>\n<span id="cb13-6"><a href="#cb13-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-7"><a href="#cb13-7" aria-hidden="true" tabindex="-1"></a><span class="co">    Подсказка: это задача ЛП с нулевой целевой функцией. Ограничения в форме</span></span>\n<span id="cb13-8"><a href="#cb13-8" aria-hidden="true" tabindex="-1"></a><span class="co">    A_ub @ z &lt;= b_ub, где z = (w, b).</span></span>\n<span id="cb13-9"><a href="#cb13-9" aria-hidden="true" tabindex="-1"></a><span class="co">    &quot;&quot;&quot;</span></span>\n<span id="cb13-10"><a href="#cb13-10" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb13-11"><a href="#cb13-11" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-12"><a href="#cb13-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-13"><a href="#cb13-13" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> shatters(X):</span>\n<span id="cb13-14"><a href="#cb13-14" aria-hidden="true" tabindex="-1"></a>    <span class="co">&quot;&quot;&quot;Реализуются ли все 2^d разметок набора точек X?&quot;&quot;&quot;</span></span>\n<span id="cb13-15"><a href="#cb13-15" aria-hidden="true" tabindex="-1"></a>    <span class="cf">raise</span> <span class="pp">NotImplementedError</span></span>\n<span id="cb13-16"><a href="#cb13-16" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-17"><a href="#cb13-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb13-18"><a href="#cb13-18" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) проверьте, что 3 точки общего положения разбиваются, а 4 -- нет</span></span>\n<span id="cb13-19"><a href="#cb13-19" aria-hidden="true" tabindex="-1"></a><span class="co">#          (и для квадрата, и для случая «точка внутри треугольника»);</span></span>\n<span id="cb13-20"><a href="#cb13-20" aria-hidden="true" tabindex="-1"></a><span class="co">#          выведите конкретную нереализуемую разметку;</span></span>\n<span id="cb13-21"><a href="#cb13-21" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) для n = 2, 3, 5 и d = 2..8 посчитайте долю реализуемых разметок</span></span>\n<span id="cb13-22"><a href="#cb13-22" aria-hidden="true" tabindex="-1"></a><span class="co">#          (усредните по 15 случайным наборам точек), сведите в таблицу</span></span>\n<span id="cb13-23"><a href="#cb13-23" aria-hidden="true" tabindex="-1"></a><span class="co">#          и постройте график с отметками d = n + 1.</span></span></code></pre></div>\n</div>\n<div id="cell031" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какая разметка четырёх точек оказалась\nнереализуемой в каждом из двух случаев? Где на графике доли разделимых\nразметок «ломается» кривая и как это связано с\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">V</mi><mi mathvariant="normal">C</mi><mi mathvariant="normal">d</mi><mi mathvariant="normal">i</mi><mi mathvariant="normal">m</mi></mrow><mo>=</mo><mi>n</mi><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">\\mathrm{VCdim} = n + 1</annotation></semantics></math>?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell032" class="cell markdown">\n<hr />\n<h1 id="часть-7-три-стратегии-выбора-модели">Часть 7. Три стратегии\nвыбора модели</h1>\n<p>Определение 4.14 (SRM): для вложенных моделей\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>A</mi><mn>1</mn></msub><mo>⊂</mo><mi>…</mi><mo>⊂</mo><msub><mi>A</mi><mi>M</mi></msub></mrow><annotation encoding="application/x-tex">A_1 \\subset \\dots \\subset A_M</annotation></semantics></math>\nвыбирается</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>m</mi><mo>*</mo></msup><mo>=</mo><mrow><mi>arg</mi><mo>⁡</mo></mrow><munder><mi>min</mi><mi>m</mi></munder><mo minsize="180%" maxsize="180%" stretchy="true" form="prefix">(</mo><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>a</mi><mi>m</mi></msub><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo><mo>+</mo><mrow><mi mathvariant="normal">p</mi><mi mathvariant="normal">e</mi><mi mathvariant="normal">n</mi><mi mathvariant="normal">a</mi><mi mathvariant="normal">l</mi><mi mathvariant="normal">t</mi><mi mathvariant="normal">y</mi></mrow><mo stretchy="false" form="prefix">(</mo><mrow><mi mathvariant="normal">V</mi><mi mathvariant="normal">C</mi><mi mathvariant="normal">d</mi><mi mathvariant="normal">i</mi><mi mathvariant="normal">m</mi></mrow><mo stretchy="false" form="prefix">(</mo><msub><mi>A</mi><mi>m</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mi>ℓ</mi><mo stretchy="false" form="postfix">)</mo><mo minsize="180%" maxsize="180%" stretchy="true" form="postfix">)</mo><mi>.</mi></mrow><annotation encoding="application/x-tex">\nm^* = \\arg\\min_m \\Bigl(Q(a_m, X^\\ell) + \\mathrm{penalty}(\\mathrm{VCdim}(A_m), \\ell)\\Bigr).\n</annotation></semantics></math></p>\n<p>Сравните три стратегии выбора степени полинома:</p>\n<ol>\n<li>по обучающей ошибке\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>a</mi><mi>m</mi></msub><mo>,</mo><msup><mi>X</mi><mi>ℓ</mi></msup><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(a_m, X^\\ell)</annotation></semantics></math>;</li>\n<li>по скользящему контролю\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">C</mi><mi mathvariant="normal">V</mi></mrow><mo stretchy="false" form="prefix">(</mo><msub><mi>μ</mi><mi>m</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\mathrm{CV}(\\mu_m)</annotation></semantics></math>;</li>\n<li>по штрафу за сложность — в качестве практического аналога VC-штрафа\nвозьмите информационные критерии\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">A</mi><mi mathvariant="normal">I</mi><mi mathvariant="normal">C</mi></mrow><mo>=</mo><mi>ℓ</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><msup><mover><mi>σ</mi><mo accent="true">̂</mo></mover><mn>2</mn></msup><mo>+</mo><mn>2</mn><mi>p</mi></mrow><annotation encoding="application/x-tex">\\mathrm{AIC} = \\ell\\ln\\widehat{\\sigma}^2 + 2p</annotation></semantics></math>\nи\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mrow><mi mathvariant="normal">B</mi><mi mathvariant="normal">I</mi><mi mathvariant="normal">C</mi></mrow><mo>=</mo><mi>ℓ</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><msup><mover><mi>σ</mi><mo accent="true">̂</mo></mover><mn>2</mn></msup><mo>+</mo><mi>p</mi><mrow><mi>ln</mi><mo>⁡</mo></mrow><mi>ℓ</mi></mrow><annotation encoding="application/x-tex">\\mathrm{BIC} = \\ell\\ln\\widehat{\\sigma}^2 + p\\ln\\ell</annotation></semantics></math>,\nгде\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>p</mi><annotation encoding="application/x-tex">p</annotation></semantics></math>\n— число параметров.</li>\n</ol>\n<p>Эталон для сравнения — истинный риск на большой независимой\nвыборке.</p>\n</div>\n<div id="cell033" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb14"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb14-1"><a href="#cb14-1" aria-hidden="true" tabindex="-1"></a>gen <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span>\n<span id="cb14-2"><a href="#cb14-2" aria-hidden="true" tabindex="-1"></a>X_s, y_s <span class="op">=</span> make_sample(<span class="dv">50</span>, gen)</span>\n<span id="cb14-3"><a href="#cb14-3" aria-hidden="true" tabindex="-1"></a>X_ref, y_ref <span class="op">=</span> make_sample(<span class="dv">20_000</span>, np.random.default_rng(<span class="dv">999</span>))</span>\n<span id="cb14-4"><a href="#cb14-4" aria-hidden="true" tabindex="-1"></a>degrees <span class="op">=</span> <span class="bu">list</span>(<span class="bu">range</span>(<span class="dv">1</span>, <span class="dv">16</span>))</span>\n<span id="cb14-5"><a href="#cb14-5" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb14-6"><a href="#cb14-6" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: для каждой степени посчитайте: Q на обучении, CV(5), AIC, BIC и</span></span>\n<span id="cb14-7"><a href="#cb14-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       ИСТИННЫЙ риск на большой выборке. Выведите, какую степень выбирает</span></span>\n<span id="cb14-8"><a href="#cb14-8" aria-hidden="true" tabindex="-1"></a><span class="co">#       каждый критерий, и постройте график.</span></span></code></pre></div>\n</div>\n<div id="cell034" class="cell markdown">\n<blockquote>\n<p><strong>Вывод.</strong> Какую степень выбрала каждая стратегия и\nкакая ближе всего к оптимуму по истинному риску? Почему выбор по\nобучающей ошибке бесполезен, и чем BIC отличается от AIC?</p>\n<p><em>(ваш ответ здесь)</em></p>\n</blockquote>\n</div>\n<div id="cell035" class="cell markdown">\n<hr />\n<h1 id="часть-8-правильный-протокол-на-своей-выборке">Часть 8.\nПравильный протокол на своей выборке</h1>\n<p>Соберите всё вместе: сравните модели из работ 2–4 на индивидуальной\nвыборке по схеме контроля из вашего варианта\n(<code>variant[&quot;cv_scheme&quot;]</code>), с полной предобработкой\n<strong>внутри</strong> <code>Pipeline</code> и честной финальной\nоценкой на отложенной контрольной выборке.</p>\n</div>\n<div id="cell036" class="cell code" data-tags="[&quot;task&quot;]">\n<div class="sourceCode" id="cb15"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb15-1"><a href="#cb15-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.svm <span class="im">import</span> SVC</span>\n<span id="cb15-2"><a href="#cb15-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.tree <span class="im">import</span> DecisionTreeClassifier</span>\n<span id="cb15-3"><a href="#cb15-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb15-4"><a href="#cb15-4" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_personal(variant)</span>\n<span id="cb15-5"><a href="#cb15-5" aria-hidden="true" tabindex="-1"></a><span class="co"># </span><span class="al">TODO</span><span class="co">: 1) при необходимости бинаризуйте цель по медиане ОБУЧАЮЩЕЙ выборки;</span></span>\n<span id="cb15-6"><a href="#cb15-6" aria-hidden="true" tabindex="-1"></a><span class="co">#       2) соберите схему контроля из variant[&quot;cv_scheme&quot;];</span></span>\n<span id="cb15-7"><a href="#cb15-7" aria-hidden="true" tabindex="-1"></a><span class="co">#       3) для трёх моделей (логистическая регрессия, SVM с RBF, дерево решений)</span></span>\n<span id="cb15-8"><a href="#cb15-8" aria-hidden="true" tabindex="-1"></a><span class="co">#          подберите гиперпараметры GridSearchCV по этой схеме;</span></span>\n<span id="cb15-9"><a href="#cb15-9" aria-hidden="true" tabindex="-1"></a><span class="co">#       4) выведите таблицу: лучшие параметры, лучшее CV-значение и AUC на</span></span>\n<span id="cb15-10"><a href="#cb15-10" aria-hidden="true" tabindex="-1"></a><span class="co">#          отложенной контрольной выборке. Объясните разницу между двумя числами.</span></span></code></pre></div>\n</div>\n<div id="cell037" class="cell markdown">\n<h2 id="итоги-работы">Итоги работы</h2>\n<p>Ответьте письменно на контрольные вопросы (по 2–4 предложения):</p>\n<ol>\n<li>Модель A: смещение большое, разброс малый. Модель B: наоборот. Какая\nиз них выиграет при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℓ</mi><mo>=</mo><mn>50</mn></mrow><annotation encoding="application/x-tex">\\ell = 50</annotation></semantics></math>\nи какая при\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>ℓ</mi><mo>=</mo><mn>50</mn><mspace width="0.167em"></mspace><mn>000</mn></mrow><annotation encoding="application/x-tex">\\ell = 50\\,000</annotation></semantics></math>?\nПочему?</li>\n<li>Почему оценка по отложенной выборке систематически пессимистична, а\n«лучшее значение по сетке гиперпараметров» — систематически\nоптимистично? Это два разных смещения или одно и то же?</li>\n<li>Ваш коллега отобрал 50 признаков из 10 000 по корреляции с целью на\nвсех данных, затем честно провёл 10-кратный контроль и получил AUC 0.85.\nЧто вы ему скажете и как перепроверите результат?</li>\n<li>VC-размерность линейного классификатора в\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><msup><mi>ℝ</mi><mi>n</mi></msup><annotation encoding="application/x-tex">\\mathbb{R}^n</annotation></semantics></math>\nравна\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi><mo>+</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">n+1</annotation></semantics></math>.\nЗначит ли это, что VC-размерность всегда равна числу параметров?\nПриведите контрпример или объясните, почему это так.</li>\n<li>Вы получили CV AUC = 0.91 и AUC на отложенной выборке = 0.86. Это\nнормально или признак ошибки? Какие три причины такого разрыва вы\nпроверите в первую очередь?</li>\n</ol>\n<h3 id="домашнее-задание">Домашнее задание</h3>\n<ol>\n<li><p><strong><math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>5</mn><mo>×</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">5\\times2</annotation></semantics></math>-кратный\nконтроль и статистическая значимость.</strong> Реализуйте схему\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>5</mn><mo>×</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">5\\times2</annotation></semantics></math>cv\n(пять независимых разбиений пополам) и постройте на её основе парный\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>t</mi><annotation encoding="application/x-tex">t</annotation></semantics></math>-тест\nдля сравнения двух моделей (Dietterich, 1998). Сравните с наивным\nподходом «10-кратный контроль + парный\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>t</mi><annotation encoding="application/x-tex">t</annotation></semantics></math>-тест\nпо блокам» на данных, где обе модели заведомо <strong>одинаковы</strong>\n(например, две копии одной модели с разным <code>random_state</code>):\nпокажите, что наивный тест отвергает нулевую гипотезу существенно чаще\nзаявленных 5 %, и объясните почему (подсказка: обучающие выборки в\nблоках перекрываются, поэтому ошибки зависимы).</p></li>\n<li><p><strong>Кривая обучения и стоимость данных.</strong> Для своей\nвыборки постройте кривую обучения для лучшей модели из части 8,\nаппроксимируйте её степенным законом\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>R</mi><mo stretchy="false" form="prefix">(</mo><mi>ℓ</mi><mo stretchy="false" form="postfix">)</mo><mo>≈</mo><msub><mi>R</mi><mi>∞</mi></msub><mo>+</mo><mi>c</mi><mspace width="0.167em"></mspace><msup><mi>ℓ</mi><mrow><mi>−</mi><mi>α</mi></mrow></msup></mrow><annotation encoding="application/x-tex">R(\\ell) \\approx R_\\infty + c\\,\\ell^{-\\alpha}</annotation></semantics></math>\n(подгонка по МНК в логарифмических координатах) и оцените, сколько\nобъектов нужно, чтобы уменьшить ошибку ещё на 10 %. Обсудите, когда\nвыгоднее собирать данные, а когда — усложнять модель, опираясь на\nразложение из части 2.</p></li>\n</ol>\n</div>\n</body>\n</html>\n'}}]);